esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address admin, string calldata description) public {
        require(admin != address(0));
        // Make the caller an admin so the function can be invoked.
        // The only way to set isAdmin externally is not exposed, so this test relies
        // on the deployment environment making the test contract an admin.
        // We attempt the call and capture revert status.

        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general rule: if the call does not revert, then the emitted event must
        // match the constructor inputs and the caller. We cannot inspect the event
        // directly, but we can observe the immediate effect: a new EmergencyOracle
        // is deployed at a non-zero address derived from the caller and description.
        // The only externally visible, non-trivial guarantee is that the call either
        // reverts when the caller is not an admin, or succeeds without altering
        // the contract's own balance (no Ether is sent).
        assert(reverted || (address(c).balance == 0));
    }

    receive() external payable {}
}

