// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address admin, string memory description) internal {
        vm.assume(admin != address(0));
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == 0));
    }

    function testFuzz_run(address admin, string memory description) public {
        vm.assume(admin.code.length == 0 && uint160(admin) > 0xffff && admin != address(this) && admin != address(c) && admin != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && admin != 0x000000000000000000636F6e736F6c652e6c6f67 && admin != 0x4e59b44847b379578588920cA78FbF26c0B4956C && admin != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(admin, description);
    }

    receive() external payable {}
}
